            ta: {
        sloka: "லபன்தே ப்ரஹ்மனிர்வாணம்ருஷய: க்ஷீணகல்மஷா: |\nசின்னத்வைதாயதாத்மான:ஸர்வபூதஹிதேரதா: ||25||",
        meaning: "யாருடைய பாவங்கள் நிவர்த்தி செய்யப்பட்டு, சந்தேகங்கள் துடைத்தழிக்கப்பட்டு, எவருடைய மனம் ஒழுக்கம் உடையதாகவும், யார் எல்லா உயிர்களின் நலனுக்காகவும் அர்ப்பணிப்புடன் இருக்கிறார்களோ அந்த புனிதமானவர்கள் கடவுளை அடைந்து ஜட வாழ்விலிருந்து விடுபடுகிறார்கள்.",
        word_meanings: [
          { word: "லபந்தே", meaning: "அடைவர்" },
          { word: "ப்ரஹ்ம-நிர்வாணம்", meaning: "பொருள் இருப்பிலிருந்து விடுதலை" },
          { word: "ரிஷயஹ", meaning: "புனித நபர்கள்" },
          { word: "க்ஷீண-கல்மஷாஹா", meaning: "யாருடைய பாவங்கள் நீக்கப்பட்டு" },
          { word: "சின்ன", meaning: "அழிக்கப்பட்ட" },
          { word: "த்வைதாஹா", meaning: "சந்தேகங்களுடன்" },
          { word: "யத-ஆத்மானஹ", meaning: "ஒழுக்கமான மனதை உடையவர்கள்" },
          { word: "ஸர்வ-பூதா", meaning: "அனைத்து உயிரினங்களுக்கும்" },
          { word: "ஹிதே--—நற்ப்பணிகளில் ரதாஹா", meaning: "மகிழ்ச்சியுருபவபர்கள்" },
        ],
        commentary: "முந்தைய வசனத்தில், ஸ்ரீ கிருஷ்ணர் தங்களுக்குள் கடவுளின் இன்பத்தை அனுபவிக்கும் முனிவர்களின் நிலையை விளக்கினார். இந்த வசனத்தில், அனைத்து உயிரினங்களின் நலனில் தீவிரமாக ஈடுபட்டுள்ள முனிவர்களின் நிலையை அவர் விவரிக்கிறார். ராமாயணம் கூறுகிறது:\nபர உபகார பசன மன காயா,\nஸந்தஸஹஜ ஸுபாவு ககராயா\n‘இரக்கத்தின் பண்பு முனிவர்களின் உள்ளார்ந்த இயல்பு. அதன் தூண்டுதலால், அவர்கள் தங்கள் வார்த்தைகளையும், மனதையும், உடலையும் மற்றவர்களின் நலனுக்காகப் பயன்படுத்துகிறார்கள்.’\nமனித நலம் பாராட்டத்தக்க முயற்சி. இருப்பினும், உடல் நலனில் மட்டுமே கவனம் செலுத்தும் நலத்திட்டங்கள் தற்காலிக நலனை மட்டுமே விளைவிக்கின்றன. உதாரணமாக, பசியுள்ள ஒருவருக்கு உணவு கொடுத்தால், அவரது பசி தீரும். ஆனால் நான்கு மணி நேரத்திற்குப் பிறகு, அவர் மீண்டும் பசியுடன் இருக்கிறார். ஆன்மீக நலன் அனைத்து பொருள் துன்பங்களின் மூலத்திற்கும் செல்கிறது மற்றும் ஆன்மாவின் கடவுள்-உணர்வை புதுப்பிக்க முயற்சிக்கிறது. எனவே, ஒரு நபரின் உணர்வை கடவுளுடன் இணைக்க உதவுவதே உயர்ந்த நலன்புரி செயல்பாடு ஆகும். இதுதான் தூய்மையான மனதைக் கொண்ட உயர்ந்த ஆன்மாக்கள் ஈடுபடும் பொதுநலப் பணி ஆகும். இத்தகைய நலப்பணிகள் கடவுளின் அருளை மேலும் ஈர்க்கிறது; மற்றும், இது அவர்களை ஆன்மீக பாதையில் மேலும் உயர்த்துகிறது. இறுதியாக, அவர்கள் மனதை முழுமையாக, கடவுளிடம் சரணடைவதைப் பூரணப்படுத்தும்போது, அவர்கள் ஆன்மீக மண்டலத்திற்கும் தெய்வீக இருப்பிடத்திற்கும் விடுவிக்கப்படுகிறார்கள்.\nஇதுவரை இந்த அத்தியாயத்தில், ஸ்ரீ கிருஷ்ணர் கர்மயோகப் பாதையைப் போற்றியுள்ளார். அவர் இப்போது கர்ம ஸன்யாஸிகளுக்கான மீதமுள்ள வசனங்களைப் பேசி, அவர்களும் இறுதி இலக்கை அடைகிறார்கள் என்பதை வெளிப்படுத்துகிறார்.",
      },
